import { readFile, writeFile } from 'node:fs/promises';
import { existsSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

// The heatmap SVGs under assets/ are pre-generated by the Python pipeline and
// embed statistic labels (distance / runs / pace / ...). When activities.json
// is edited without re-running that pipeline, those baked-in numbers go stale
// and contradict the live numbers the frontend derives from activities.json.
// This script rewrites the stat texts from activities.json — with the same
// filter (type === 'Run') and the same pace formula as the frontend — right
// before the site is built, so both surfaces always agree.

const rootDir = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const activitiesPath = resolve(rootDir, 'src/static/activities.json');

const M_TO_DIST = 1000;

const formatPace = (metersPerSecond) => {
  if (!Number.isFinite(metersPerSecond) || metersPerSecond <= 0) return '0';
  const pace = (M_TO_DIST / 60.0) * (1.0 / metersPerSecond);
  const minutes = Math.floor(pace);
  const seconds = Math.floor((pace - minutes) * 60.0);
  return `${minutes}'${String(seconds).padStart(2, '0')}"`;
};

const movingTimeToSeconds = (movingTime) => {
  if (!movingTime) return 0;
  const [h = 0, m = 0, s = 0] = String(movingTime).split(':').map(Number);
  return h * 3600 + m * 60 + s;
};

// Arial glyph widths (relative to font size) — enough precision to place the
// unit label after a rewritten value without overlap.
const glyphWidth = (ch) => {
  if (ch >= '0' && ch <= '9') return 0.556;
  if (ch === '.') return 0.278;
  if (ch === "'") return 0.191;
  if (ch === '"') return 0.355;
  return 0.556;
};
const textWidth = (text, fontSize) =>
  [...text].reduce((w, ch) => w + glyphWidth(ch) * fontSize, 0);

const computeStats = (runs) => {
  const distanceMeters = runs.reduce((sum, r) => sum + (r.distance || 0), 0);
  let paceMeters = 0;
  let paceSeconds = 0;
  for (const r of runs) {
    if (r.average_speed) {
      paceMeters += r.distance || 0;
      paceSeconds += (r.distance || 0) / r.average_speed;
    }
  }
  const dates = runs.map((r) => r.start_date_local.slice(0, 10)).sort();
  const spanDays = dates.length
    ? Math.round(
        (new Date(dates[dates.length - 1]) - new Date(dates[0])) / 86400000
      ) + 1
    : 0;
  return {
    count: runs.length,
    distanceKm: (distanceMeters / M_TO_DIST).toFixed(1),
    pace: formatPace(paceSeconds > 0 ? paceMeters / paceSeconds : 0),
    streak: runs.reduce((max, r) => Math.max(max, r.streak || 0), 0),
    hours: Math.floor(
      runs.reduce((sum, r) => sum + movingTimeToSeconds(r.moving_time), 0) /
        3600
    ),
    longestKm: (
      runs.reduce((max, r) => Math.max(max, r.distance || 0), 0) / M_TO_DIST
    ).toFixed(1),
    spanDays,
    avgKm: runs.length
      ? (distanceMeters / M_TO_DIST / runs.length).toFixed(1)
      : '0.0',
    minKm: runs.length
      ? (
          runs.reduce(
            (min, r) => Math.min(min, r.distance || Infinity),
            Infinity
          ) / M_TO_DIST
        ).toFixed(1)
      : '0.0',
    weekly: spanDays ? (runs.length / (spanDays / 7)).toFixed(1) : '0.0',
  };
};

// Replace the text content of the <text> node that immediately follows the
// node containing `label`, and (optionally) re-anchor the unit label that
// comes right after the value so it never overlaps the new text.
const replaceValueAfterLabel = (svg, label, newValue, unitFontAnchor) => {
  const labelToken = `>${label}</text>`;
  const labelIndex = svg.indexOf(labelToken);
  if (labelIndex === -1) return svg;
  const windowStart = labelIndex + labelToken.length;
  const window = svg.slice(windowStart, windowStart + 400);
  const valueMatch = window.match(/(<text\b[^>]*>)([^<]*)(<\/text>)/);
  if (!valueMatch) return svg;
  let replacedWindow =
    window.slice(0, valueMatch.index) +
    valueMatch[1] +
    newValue +
    valueMatch[3] +
    window.slice(valueMatch.index + valueMatch[0].length);
  if (unitFontAnchor) {
    const { unit, valueX, fontSize } = unitFontAnchor;
    const unitX = (valueX + textWidth(newValue, fontSize) + 1.5).toFixed(1);
    const afterValue = valueMatch.index + valueMatch[0].length;
    const unitWindow = replacedWindow.slice(afterValue, afterValue + 200);
    const unitMatch = unitWindow.match(
      new RegExp(`(<text\\b[^>]*x=")[\\d.]+("[^>]*>${unit}</text>)`)
    );
    if (unitMatch) {
      replacedWindow =
        replacedWindow.slice(0, afterValue) +
        unitWindow.slice(0, unitMatch.index) +
        unitMatch[1] +
        unitX +
        unitMatch[2] +
        unitWindow.slice(unitMatch.index + unitMatch[0].length) +
        replacedWindow.slice(afterValue + unitWindow.length);
    }
  }
  return (
    svg.slice(0, windowStart) +
    replacedWindow +
    svg.slice(windowStart + window.length)
  );
};

const refreshYearSummary = async (year, stats) => {
  const svgPath = resolve(rootDir, `assets/year_summary_${year}.svg`);
  if (!existsSync(svgPath)) return false;
  let svg = await readFile(svgPath, 'utf8');
  const original = svg;

  svg = svg.replace(
    /Running for \d+ Days/,
    `Running for ${stats.spanDays} Days`
  );
  svg = replaceValueAfterLabel(svg, 'Distance', stats.distanceKm, {
    unit: 'km',
    valueX: 11,
    fontSize: 10,
  });
  svg = replaceValueAfterLabel(svg, 'Runs', String(stats.count));
  svg = replaceValueAfterLabel(svg, 'Avg Pace', stats.pace);
  svg = replaceValueAfterLabel(svg, 'Streak', String(stats.streak), {
    unit: 'd',
    valueX: 53,
    fontSize: 10,
  });
  svg = replaceValueAfterLabel(svg, 'Time', String(stats.hours), {
    unit: 'h',
    valueX: 11,
    fontSize: 10,
  });
  svg = replaceValueAfterLabel(svg, 'Longest', stats.longestKm);

  if (svg !== original) {
    await writeFile(svgPath, svg);
    return true;
  }
  return false;
};

const refreshGithubTotal = async (totalStats, statsByYear) => {
  const svgPath = resolve(rootDir, 'assets/github.svg');
  if (!existsSync(svgPath)) return false;
  let svg = await readFile(svgPath, 'utf8');
  const original = svg;

  svg = svg
    .replace(/Number: \d+/, `Number: ${totalStats.count}`)
    .replace(/Weekly: [\d.]+/, `Weekly: ${totalStats.weekly}`)
    .replace(/Total: [\d.]+ km/, `Total: ${totalStats.distanceKm} km`)
    .replace(/Avg: [\d.]+ km/, `Avg: ${totalStats.avgKm} km`)
    .replace(/Min: [\d.]+ km/, `Min: ${totalStats.minKm} km`)
    .replace(/Max: [\d.]+ km/, `Max: ${totalStats.longestKm} km`);

  for (const [year, stats] of statsByYear) {
    svg = svg.replace(
      new RegExp(`(>${year}</text><text\\b[^>]*>)[\\d.]+ km(</text>)`),
      `$1${stats.distanceKm} km$2`
    );
  }

  if (svg !== original) {
    await writeFile(svgPath, svg);
    return true;
  }
  return false;
};

const main = async () => {
  const activities = JSON.parse(await readFile(activitiesPath, 'utf8'));
  const runs = activities.filter((a) => a.type === 'Run');
  if (!runs.length) {
    console.log('refresh-svg-stats: no runs in activities.json, skipped');
    return;
  }

  const statsByYear = new Map();
  for (const run of runs) {
    const year = run.start_date_local.slice(0, 4);
    if (!statsByYear.has(year)) statsByYear.set(year, []);
    statsByYear.get(year).push(run);
  }
  for (const [year, yearRuns] of statsByYear) {
    statsByYear.set(year, computeStats(yearRuns));
  }

  const updated = [];
  for (const [year, stats] of statsByYear) {
    if (await refreshYearSummary(year, stats)) {
      updated.push(`year_summary_${year}.svg`);
    }
  }
  if (await refreshGithubTotal(computeStats(runs), statsByYear)) {
    updated.push('github.svg');
  }

  console.log(
    updated.length
      ? `refresh-svg-stats: updated ${updated.join(', ')}`
      : 'refresh-svg-stats: all SVG stats already up to date'
  );
};

await main();
